def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the dictionary appearing later in the arguments will override the earlier one.
    The output dictionary should be sorted by keys.
    """
    merged_dict = dict1.copy()  # Start with the first dictionary
    merged_dict.update(dict2)   # Merge the second dictionary
    merged_dict.update(dict3)   # Merge the third dictionary
    return dict(sorted(merged_dict.items()))  # Sort the dictionary by keys

# Test cases
assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "O": "Orange", "W": "White", "B": "Black" }
) == {'B': 'Black', 'G': 'Green', 'O': 'Orange', 'P': 'Pink', 'R': 'Red', 'W': 'White'}

